LLM output
→ extract claims
→ classify claim type
→ demand evidence
→ Poseidon verify
→ only VERIFIED_RESULT can enter memory/goals/self-model

export const CLAIM_TYPE = {
  OBSERVATION: 'OBSERVATION',
  INFERENCE: 'INFERENCE',
  PLAN: 'PLAN',
  INTENTION: 'INTENTION',
  ACTION: 'ACTION',
  RESULT: 'RESULT',
};

export const CLAIM_STATUS = {
  PROPOSED: 'PROPOSED',
  PENDING_EVIDENCE: 'PENDING_EVIDENCE',
  VERIFIED: 'VERIFIED',
  REJECTED: 'REJECTED',
  EXPIRED: 'EXPIRED',
};

const MEMORY_SAFE_TYPES = new Set([
  CLAIM_TYPE.OBSERVATION,
  CLAIM_TYPE.ACTION,
  CLAIM_TYPE.RESULT,
]);

function canEnterMemory(claim) {
  return (
    claim.status === CLAIM_STATUS.VERIFIED &&
    MEMORY_SAFE_TYPES.has(claim.type)
  );
}

if (claim.type === CLAIM_TYPE.INTENTION || claim.type === CLAIM_TYPE.PLAN) {
  claim.status = CLAIM_STATUS.PENDING_EVIDENCE;
  claim.memorySafe = false;
}

async processClaim(text, {
  type,
  evidence = [],
  falsificationTest = null,
  testResult = null,
  expiresAt = null,
} = {}) {
  const claim = {
    id: crypto.randomUUID(),
    text,
    type,
    evidence,
    status: CLAIM_STATUS.PROPOSED,
    memorySafe: false,
    createdAt: new Date().toISOString(),
    expiresAt,
  };

  if (type === CLAIM_TYPE.INTENTION || type === CLAIM_TYPE.PLAN) {
    claim.status = CLAIM_STATUS.PENDING_EVIDENCE;
    return claim;
  }

  const verdict = await this.poseidon.verify(text, {
    falsificationTest,
    testResult,
  });

  if (verdict.state === 'TRUE') {
    claim.status = CLAIM_STATUS.VERIFIED;
    claim.memorySafe = canEnterMemory(claim);
  } else if (verdict.state === 'FALSE') {
    claim.status = CLAIM_STATUS.REJECTED;
  } else {
    claim.status = CLAIM_STATUS.PENDING_EVIDENCE;
  }

  return claim;
}

